/* Review prototype; persistent device/Drive backups are opt-in via Settings. */
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = cents => '₹' + (cents / 100).toLocaleString('en-IN', {minimumFractionDigits:cents%100?2:0,maximumFractionDigits:2});
const signed = cents => (cents >= 0 ? '+' : '−') + money(Math.abs(cents));
const initial = () => ({id:'demo-friday',name:'Friday Night',banker:'You',small:50,big:100,rake:40000,closed:false,mode:'banker',
 players:[{id:1,name:'Alex Morgan',phone:'',buy:500000,last:500000,out:null,paidIn:500000,paidOut:0},{id:2,name:'Jamie Chen',phone:'',buy:500000,last:500000,out:null,paidIn:500000,paidOut:0},{id:3,name:'Sam Rivera',phone:'',buy:500000,last:500000,out:720000,paidIn:500000,paidOut:0},{id:4,name:'Taylor Reed',phone:'',buy:500000,last:500000,out:380000,paidIn:500000,paidOut:380000}],
 events:[{title:'Rake added',detail:'₹200 · Friday Night · 21:42'},{title:'Rake added',detail:'₹200 · Friday Night · 21:06'},{title:'Sam cashed out',detail:'₹7,200 · Friday Night · 21:00'},{title:'Taylor cashed out & paid',detail:'₹3,800 · Friday Night · 20:48'},{title:'Four initial buy-ins',detail:'₹5,000 each · Friday Night · 19:30'}]});
const isPlatform=Boolean(window.CASH_OUT_PLATFORM);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const emptyTable=()=>({id:crypto.randomUUID(),name:'Your first table',date:today(),banker:'You',small:50,big:100,rake:0,closed:false,mode:'banker',callTimeMinutes:180,players:[],events:[]});
const seededHistory=isPlatform?{contacts:[],tables:[]}:CashHistory.seed();
let historyTables=seededHistory.tables, selectedHistoryId=historyTables.at(-1)?.id;
let table=isPlatform?emptyTable():initial(), view=isPlatform?'tables':'table', profileId=null, historyView=false, contacts=seededHistory.contacts, payments=[], draft=null, nextId=16;
let historyFilter='all';
let savedContactId=null;
let playerFilter='all',profileTab='overview',profileSession=null;
let toastTimer;
const sheet=$('#sheet');
const totalBuy=()=>table.players.reduce((s,p)=>s+p.buy,0);
const totalOut=()=>table.players.reduce((s,p)=>s+(p.out??p.priorOut??0),0);
const remaining=()=>CashCore.balance(table).difference;
const playing=()=>table.players.filter(p=>p.out===null);
const avatar=p=>CashUI.avatar(p);
const btn=(label,action,cls='secondary',extra='')=>CashUI.button({content:label,action,variant:cls,attributes:extra});
const firstRunHeading=(title,sub='')=>`<div class="title-row first-run-heading"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${btn(CashUI.icon('settings',18),'settings','icon first-run-settings','aria-label="Settings"')}</div>`;
const header=(title,sub,extra='')=>`<div class="topline app-context"><span class="app-context-label">Private poker accounting</span>${btn(CashUI.icon('settings'),'settings','icon','aria-label="Settings"')}</div>${extra.includes('‹')?`<div class="back-navigation">${extra}</div>`:''}<div class="title-row"><div><h2>${esc(title)}</h2><p>${sub}</p></div>${extra.includes('‹')?'':extra}</div>`;
function notify(text){
  if(sheet.open){
    let message=$('#sheet-feedback');
    if(!message){message=document.createElement('p');message.id='sheet-feedback';message.className='notice';message.setAttribute('role','alert');$('#sheet-body').prepend(message)}
    message.textContent=text;
    return;
  }
  clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').style.display='block';CashMotion.enter($('#toast'),'content');toastTimer=setTimeout(()=>$('#toast').style.display='none',3200);
}

async function persistChange(kind,change,meta={}){if(isPlatform)return CashBackupUI.commit({kind,...meta},change);return change()}
function event(title,detail){if(isPlatform)return;table.events.unshift({id:crypto.randomUUID(),timestamp:new Date().toISOString(),table:{id:table.id,name:table.name,currency:'INR',smallBlind:table.small,bigBlind:table.big},title,detail:`${detail} · ${table.name} · just now`})}
function go(next){view=next;profileId=null;render();window.scrollTo(0,0)}
let lastRenderedView=null;
function render(){return window.CashPremium?CashPremium.render(paintApp,view):paintApp()}
function paintApp(){
 const pages={table:tablePage,tables:tablesPage,players:playersPage,history:historyPage,settings:settingsPage,review:reviewPage,settle:settlePage,insights:insightsPage,profile:profilePage,'contact-saved':contactSavedPage,'history-detail':historyDetailPage};
 const html=pages[view]();$('#app').setAttribute('data-first-run',String(html.includes('first-run-heading')));$('#app').innerHTML=html;
 window.CashPolish?.mount($('#app'),lastRenderedView!==view);
 lastRenderedView=view;
 window.CashBackupUI?.capture();
 window.CashDeviceUI?.mount();
 const selected=historyView&&['settle','history-detail'].includes(view)?'history':['table','tables','review','settle'].includes(view)?'tables':['profile','contact-saved'].includes(view)?'players':view;
 renderNavigation(selected);
}
function renderNavigation(selected){
 const node=$('#navigation'),items=[['tables','tables','Tables'],['players','players','Players'],['history','history','History'],['insights','insights','Insights']];
 if(!node.querySelector('.nav'))node.innerHTML=`<div class="nav"><span class="nav-selection" aria-hidden="true"></span>${items.map(([id,icon,label])=>btn(`<span aria-hidden="true">${CashUI.icon(icon)}</span><span class="nav-label">${label}</span>`,'nav','',`data-value="${id}"`)).join('')}</div>`;
 const nav=node.querySelector('.nav'),index=items.findIndex(([id])=>id===selected);
 nav?.style.setProperty('--nav-index',Math.max(0,index));
 nav?.classList.toggle('has-selection',index>=0);
 for(const button of node.querySelectorAll('[data-action="nav"]')){
  const current=button.dataset.value===selected;button.classList.toggle('active',current);
  if(current)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
 }

}
function playerCard(p){return CashUI.playerCard(p,playerNet(p))}
function filteredPlayers(filter=playerFilter){return CashCore.filterPlayers(table,payments,filter)}
function playerFilters(){return `<div class="player-filters" role="group" aria-label="Filter table players">${[['all','All'],['playing','Playing'],['cashed','Cashed out'],['outstanding','Payment due']].map(([id,label])=>btn(`<span>${label}</span><span class="filter-count">${filteredPlayers(id).length}</span>`,'player-filter',playerFilter===id?'active':'',`data-value="${id}" aria-pressed="${playerFilter===id}"`)).join('')}</div>`}
function tableRoster(){if(!table.players.length)return CashUI.empty({title:'Your first seat is open',description:'Add a player and review their buy-in. They join only after you confirm.',actionLabel:'Add your first player'});return filteredPlayers().map(playerCard).join('')||CashUI.empty({title:playerFilter==='outstanding'?'No payments outstanding':playerFilter==='playing'?'No players still playing':'No players cashed out yet',description:'This filter changes the player list only. Table totals include everyone.'})}
function tablePage(){if(table.type==='tournament')return tournamentPage();if(!table.players.length)return `<div class="topline">${btn('‹ All tables','tables','back')}<span class="tag green">Private · host only</span></div><div class="title-row"><div><h2>${esc(table.name)}</h2><p>Banker: ${esc(table.banker)}</p></div>${btn(CashUI.icon('more'),'table-menu','icon','aria-label="Table options"')}</div>${CashUI.emptyScene({title:'The table is ready.',description:'Add someone from your contacts or create a new player. They join after you review and confirm their buy-in.',primary:{label:'Add your first player',action:'add-player'},footnote:'No players seated. No buy-ins recorded.'})}`;return `<div class="topline">${btn('‹ All tables','tables','back')}<span class="tag green">◦ Private · host only</span></div><div class="title-row"><div><h2>${esc(table.name)}</h2><p>${isPlatform?esc(table.date):'Tonight'} · ${esc(table.banker)} banking · ${table.players.length} ${table.players.length===1?'player':'players'}</p></div>${btn(CashUI.icon('more'),'table-menu','icon','aria-label="Table options"')}</div><section class="hero table-overview"><div class="table-overview-total"><span class="eyebrow">TABLE BUY-INS</span><div class="amount">${money(totalBuy())}</div></div><div class="metrics"><div><small>Cash-out stacks</small><strong>${money(totalOut())}</strong></div><div><small>${playing().length?'Still on the table':'Balance difference'}</small><strong class="${remaining()<0?'negative':''}">${money(remaining())}</strong></div></div></section><div class="section-head"><h3>At the table <small> / ${playing().length} playing</small></h3>${btn(table.closed?'Start a new table':'+ Add player',table.closed?'new-table':'add-player','text-button')}</div>${playerFilters()}<div class="players" aria-live="polite">${tableRoster()}</div><div class="rake"><div class="avatar">${CashUI.icon('chip')}</div><div><strong>Rake <button type="button" class="tag rake-total" data-action="rake-edit" aria-label="Correct rake total">${money(table.rake)} ${CashUI.icon('more',12)}</button></strong><small>Kept separate · distributed outside app</small></div>${btn('+ Add','rake','text-button',!table.players.length?'disabled':'')}</div><div class="section-head">${btn(`${money(table.small*100)} / ${money(table.big*100)} stakes`,'stakes','text-button')}${btn('Activity ↗','activity','text-button')}</div>${remaining()<0?'<div class="notice">Cash-outs + rake exceed buy-ins. Review entries.</div>':''}<div class="actions">${btn(!table.players.length?'Add players to begin':table.closed?'View settlement':'Review & end table',table.closed?'settle':'review','primary',!table.players.length?'disabled':'')}</div><p class="hint">${!table.players.length?'No buy-ins recorded yet.':playing().length?`${playing().length} ${playing().length===1?'player still needs':'players still need'} a cash-out.`:'All stacks entered. Check the balance before settling.'}<br>${window.CashBackupUI?.state()?.enabled?'Confirmed records autosave on this device.':'Enable device autosave in Settings to keep prototype changes.'}</p>`}
function quietArtwork(){return `<svg class="quiet-art" viewBox="0 0 280 190" aria-hidden="true" focusable="false"><defs><linearGradient id="felt-card" x2="1" y2="1"><stop stop-color="#d5ecdf"/><stop offset="1" stop-color="#8bb49b"/></linearGradient><linearGradient id="felt-chip" x2=".4" y2="1"><stop stop-color="#63e9ab"/><stop offset="1" stop-color="#118351"/></linearGradient></defs><ellipse cx="145" cy="164" rx="101" ry="13" fill="#000" opacity=".16"/><g transform="translate(45 32) rotate(-17 51 62)"><rect width="92" height="125" rx="13" fill="#16392d" stroke="#72af8e"/><rect x="7" y="7" width="78" height="111" rx="8" fill="none" stroke="#72af8e" opacity=".45"/><path d="M19 15L73 110M12 38L61 119M38 7L84 89M73 15L19 110M84 38L35 119M54 7L8 89" stroke="#72af8e" opacity=".2"/></g><g transform="translate(117 13) rotate(13 46 65)"><rect x="1" y="5" width="93" height="129" rx="13" fill="#051c12"/><rect width="93" height="129" rx="13" fill="url(#felt-card)"/><path d="M46 41C38 53 23 59 25 71C26 83 40 85 46 74C46 83 42 90 39 94H54C49 87 47 82 47 74C55 86 69 82 69 72C69 60 54 49 46 41Z" fill="#112f22"/><path d="M15 14L10 23H20Z" fill="#173a28"/><path d="M78 115L73 106H83Z" fill="#173a28"/></g><g transform="translate(198 137)"><ellipse cy="16" rx="33" ry="16" fill="#064b2d" stroke="#53c68a"/><path d="M-33 1V15M33 1V15" stroke="#53c68a"/><ellipse cy="7" rx="33" ry="16" fill="#097044" stroke="#53c68a"/><ellipse rx="33" ry="16" fill="url(#felt-chip)" stroke="#9ff1c6"/><ellipse rx="23" ry="10" fill="none" stroke="#d5ffe6" opacity=".55"/><path d="M0-16V-10M0 16V10M-33 0H-23M33 0H23M-23-11L-17-7M23-11L17-7M23 11L17 7M-23 11L-17 7" stroke="#d8ffe9" stroke-width="4"/></g><path d="M39 17V27M34 22H44M236 59V69M231 64H241" stroke="currentColor" opacity=".45"/></svg>`}
function calmEmpty(title,description,label,action){return `<article class="calm-empty">${quietArtwork()}<h3>${esc(title)}</h3><p>${esc(description)}</p><footer>${btn(label,action,'primary')}</footer></article>`}
function untouchedWorkspace(){return isPlatform&&!table.players.length&&!statsTables().length&&table.name==='Your first table'}
function tablesPage(){
 if(untouchedWorkspace())return firstRunHeading('Your tables','Good company. Clear accounts.')+CashUI.emptyScene({title:'Your first game starts here.',description:'From the first buy-in to the final payout, keep the numbers together.',primary:{label:'Create a cash table',action:'new-table'},secondary:{label:'Start tournament',action:'new-tournament'}})+`<button type="button" class="first-run-setup" data-action="my-contact"><span class="setup-avatar">${CashUI.icon('players')}</span><span><strong>${myContact()?'Your contact is ready':'Make hosting yours'}</strong><small>${myContact()?'Use it as banker on your next game.':'Save your contact once. Reuse it as banker.'}</small></span>${CashUI.icon('arrow',17)}</button>`;

 const recent=[...statsTables()].reverse().slice(0,3);
 return header('Your tables','Pick up where the evening left off.',`<div class="table-create-actions">${btn('+ Cash table','new-table','text-button')}${btn('Start tournament','new-tournament','text-button')}</div>`)+`<article class="list-card resume-table"><header><span class="tag green">${table.closed?'Completed':table.players.length?'In play':'Ready to start'}</span><small>${esc(table.date||'Tonight')}</small></header><h3>${esc(table.name)}</h3><p>${table.type==='tournament'?'Tournament · ':''}${table.players.length} ${table.players.length===1?'player':'players'} · Banker: ${esc(table.banker)}</p><div class="metrics"><div><small>Total buy-ins</small><strong>${money(totalBuy())}</strong></div><div><small>Still playing</small><strong>${table.type==='tournament'?(table.closed?0:CashTournament.active(table).length):playing().length}</strong></div></div><footer>${btn(table.closed?'View table':'Resume table →','table','primary')}</footer></article>${recent.length?`<div class="section-head"><h3>Recent nights</h3>${btn('View all','history','text-button')}</div>${recent.map(t=>recentCard(t)).join('')}`:'<p class="home-history-note">Completed tables will appear here, ready for the next day.</p>'}`;
}

function recentCard(t=historyTables.at(-1)){if(!t)return '';const due=CashCore.suggestTransfers(CashCore.obligations(t,t.payments),'banker').length;return `<article class="list-card history-card"><div class="topline"><span class="tag green">Balanced</span><small>${esc(t.date)}${isPlatform?'':' · sample'}</small></div><h3>${esc(t.name)}</h3><p>${t.players.length} players · ${money(t.players.reduce((n,p)=>n+p.buy,0))} buy-ins · ${money(t.type==='tournament'?CashTournament.fees(t):t.rake)} ${t.type==='tournament'?'fees · tournament':'rake'}</p><div class="row"><span>Payments</span><strong class="${due?'owed':'positive'}">${due?due+' transfers outstanding':'All recorded'}</strong></div>${btn('Results & settlement →','recent','secondary',`data-table-id="${esc(t.id)}"`)}</article>`}
function hasOpenGame(){return !untouchedWorkspace()&&!table.closed}
function myContact(includeArchived=false){return contacts.find(p=>p.isSelf&&(includeArchived||!p.archived))}
function contactSavedPage(){const p=contacts.find(p=>p.id===savedContactId);if(!p)return playersPage();return `<div class="contact-success-mark">${CashUI.icon('check',32)}</div>`+firstRunHeading('You’re on the list.')+`<p class="first-run-intro">Ready to host. Your contact can be selected as banker on your next game.</p><article class="contact-saved-card"><div>${avatar(p)}<span><h3>${esc(p.name)}</h3><small>${esc(p.phone||'No phone number added')}</small></span></div><footer><span class="my-contact-badge">${CashUI.icon('check',12)} My contact</span><small>Saved to your contacts</small></footer></article><div class="actions contact-saved-actions">${btn((hasOpenGame()?'Back to your table':'Create a game')+' '+CashUI.icon('arrow',17),hasOpenGame()?'table':'new-table','primary')}${btn('Go to contacts','players','secondary')}</div>${btn('Edit contact','my-contact','text-button contact-edit-link')}`}
function playersPage(){if(!contacts.some(p=>!p.archived))return firstRunHeading('Your players','Keep your regulars close.')+CashUI.emptyScene({kind:'contacts',title:'Start with a familiar face. Yours.',description:'Save yourself first, then add your friends. Choose anyone from this list when you host a game.',primary:{label:myContact(true)?'Restore my contact':'Create my contact',action:'my-contact'},secondary:{label:'Add someone else',action:'new-player'},footnote:'Name required. Phone and photo optional.'});return header('Your players','Familiar faces. A fresh table.',btn('+ New','new-player','text-button'))+`<label class="sr-only" for="player-search">Search saved players</label><input class="search" id="player-search" type="search" placeholder="Search saved players"><div id="roster">${roster('')}</div>${!myContact()?btn('Create my contact','my-contact','text-button'):''}<p class="hint">Saving a contact doesn’t add a seat. Archiving keeps their table history.</p>`}

function roster(query){return contacts.filter(p=>!p.archived&&p.name.toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="player roster-card"><div class="player-top">${avatar(p)}<div class="player-name"><h3>${esc(p.name)}${p.isSelf?'<span class="my-contact-badge">Me</span>':''}</h3><small>${p.phone?esc(p.phone):'No phone number added'}</small></div>${btn(CashUI.icon('arrow'),'profile','icon',`data-id="${p.id}" aria-label="Open ${esc(p.name)}"`)}</div></article>`).join('')||'<div class="empty"><p>No matching players.</p></div>'}
function profileStats(){return CashHistory.stats(statsTables(),profileId)}
function profilePage(){
 const p=contacts.find(x=>x.id===profileId);if(!p)return header('Player unavailable','This player is no longer in the saved roster.',btn('‹ Players','players','text-button'));
 const s=profileStats(),seated=table.players.some(x=>x.id===p.id);
 return header('Player profile','Your records, session by session.',btn('‹ Players','players','text-button'))+`<div class="co-profile-identity"><div class="profile-heading">${avatar(p)}<div><h2>${esc(p.name)}${p.isSelf?'<span class="my-contact-badge">My contact</span>':''}</h2><p class="muted">${esc(p.phone||'Phone number not added')}</p></div></div>${btn(CashUI.icon('settings'),'edit-player','icon',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`)}</div><div class="actions profile-seat-action">${btn(!hasOpenGame()?'Create a game to add player':seated?'Already at this table':'Add to table',hasOpenGame()?'seat':'new-table','primary',`data-id="${p.id}" ${hasOpenGame()&&seated?'disabled':''}`)}</div>${CashProfile.summary(s)}${CashProfile.tabs(profileTab,s.sessions)}<section id="profile-panel" role="tabpanel" aria-labelledby="profile-tab-${profileTab}" tabindex="0">${profilePanel(s)}</section><details class="co-player-options"><summary>Player options</summary><div class="actions">${btn('Edit player','edit-player','secondary',`data-id="${p.id}"`)}${btn('Archive player','archive','secondary destructive',`data-id="${p.id}"`)}</div><p class="hint">Archiving keeps past table records.</p></details>`;
}

function profilePanel(s=profileStats()){return profileTab==='overview'?CashProfile.chart(s.trend,profileSession??s.trend.length-1)+'<div class="section-head"><h3>By the numbers</h3></div>'+CashProfile.statistics(s):'<div class="section-head"><h3>Completed sessions</h3><small>Latest first</small></div>'+CashProfile.sessions(s.recent)}
function historyPage(){const all=statsTables();if(!all.length)return firstRunHeading('Table history','The nights worth keeping.')+CashUI.emptyScene({kind:'history',title:'A good night leaves a record.',description:'Your completed cash games and tournaments will appear here, with results, receipts and any payments still due.',primary:{label:!untouchedWorkspace()&&!table.closed?'Back to your table':'Create your first game',action:!untouchedWorkspace()&&!table.closed?'table':'new-table'},footnote:'Complete a game to begin your history.'});const shown=all.filter(t=>historyFilter==='all'||(t.type==='tournament'?'tournament':'cash')===historyFilter);return header('Table history',`${all.length} completed tables · results and payments`)+CashUI.segment([{value:'all',label:'All nights'},{value:'cash',label:'Cash games'},{value:'tournament',label:'Tournaments'}],historyFilter,'history-filter','History game type')+(shown.length?[...shown].reverse().map(t=>recentCard(t)).join(''):calmEmpty('Your next story starts here.',all.length?'No completed records in this category.':'Completed, balanced tables appear here with results and payment records.',table.players.length?'Back to your table':'Start a table',table.players.length?'table':'new-table'))+`<p class="hint">Results are separate from actual payments. Live tables appear here after they are finished.</p>`}

function reviewPage(){if(table.type==='tournament')return tournamentPage();
 const check=CashCore.balance(table),n=check.pending.length;
 const stackRow=p=>`<div class="payment stack-row">${avatar(p)}<div class="grow"><strong>${esc(p.name)}</strong><small>${p.out===null?'Stack not entered':money(p.out)}</small></div>${btn(p.out===null?'Enter stack':'Edit','cashout','',`data-id="${p.id}" aria-label="${p.out===null?'Enter stack for':'Edit stack for'} ${esc(p.name)}"`)}</div>`;
 return header('Finish the table',esc(table.name)+' · review every stack',btn('‹ Table','table','text-button'))+
 `${!table.players.length?'<div class="notice">Add a player and buy-in before closing this table.</div>':''}
 ${n?`<section class="review-next" aria-labelledby="missing-stacks-heading"><div class="section-head"><h3 id="missing-stacks-heading">${n} ${n===1?'stack':'stacks'} to enter</h3><span class="tag warning">Next step</span></div><p>Enter each player’s whole remaining stack, including zero.</p>${check.pending.map(stackRow).join('')}</section>`:''}
 ${CashUI.tableCheck({...check,rake:table.rake})}
 ${table.players.some(p=>p.out!==null)?`<details class="stack-records"><summary>Review ${table.players.filter(p=>p.out!==null).length} recorded ${table.players.filter(p=>p.out!==null).length===1?'stack':'stacks'}</summary>${table.players.filter(p=>p.out!==null).map(stackRow).join('')}</details>`:''}
 <div class="actions review-close-actions">${btn('Confirm table & settle','close-table','primary',check.balanced?'':'disabled')}${btn('Review activity','activity','text-button')}</div><p class="hint">${n?'Enter the missing stacks to enable confirmation.':check.balanced?'The table balances. Confirm to review who pays whom.':'The table must balance exactly before it can close.'}</p>`;
}

function recentData(){return historyTables.find(t=>t.id===selectedHistoryId)}
function paymentRecords(){return historyView?recentData().payments:payments}
function statsTables(){return [...historyTables,...(table.closed?[{...table,date:table.date||today(),payments}]:[])]}
function stat(label,value,tone=''){return `<div><small>${esc(label)}</small><strong class="${tone}">${value}</strong></div>`}
function resultMetric(value){return value===null?'—':signed(value)}
function trendChart(rows){
 if(!rows.length)return '<p class="hint">Close a balanced table to see a trend.</p>';
 const values=[0,...rows.map(r=>r.cumulative)],lo=Math.min(...values),hi=Math.max(...values),range=hi-lo||1;
 const y=v=>100-(v-lo)/range*80,x=i=>10+i/(values.length-1)*280;
 const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' '),last=values.at(-1);
 return `<figure class="trend"><div class="trend-caption"><strong class="${last>=0?'positive':'negative'}">${signed(last)}</strong><small>${rows.length} sessions · starts at zero</small></div><svg viewBox="0 0 300 120" role="img" aria-label="Cumulative result: ${esc(rows.map(r=>r.date+' '+signed(r.cumulative)).join('; '))}"><line x1="10" x2="290" y1="${y(0)}" y2="${y(0)}" stroke="var(--line)" stroke-dasharray="4 4"/><polyline points="${points}" fill="none" stroke="var(--accent)" stroke-width="2.5" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="var(--accent)"/>`).join('')}</svg><figcaption><span>${esc(rows[0].date)}</span><span>${esc(rows.at(-1).date)}</span></figcaption></figure>`;
}
function historyDetailPage(){const t=recentData();if(t.type==='tournament')return tournamentHistoryPage(t);const buy=t.players.reduce((n,p)=>n+p.buy,0);return header(t.name,`${esc(t.date)} · completed ${isPlatform?'saved':'sample'} table`,btn('‹ History','history','text-button'))+`<div class="notice good">All ${t.players.length} stacks entered · difference ${money(buy-t.players.reduce((n,p)=>n+p.out,0)-t.rake)}</div><div class="stats stats-main">${stat('Buy-ins',money(buy))}${stat('Cash-outs',money(buy-t.rake))}${stat('Rake',money(t.rake))}</div><div class="section-head"><h3>Final results</h3><small>Cash-out − buy-in</small></div>${[...t.players].sort((a,b)=>(b.out-b.buy)-(a.out-a.buy)).map(p=>`<button class="session-row" data-action="profile" data-id="${p.id}">${avatar(p)}<span class="grow"><strong>${esc(p.name)}</strong><small>In ${money(p.buy)} · out ${money(p.out)}</small></span><strong class="${p.out>=p.buy?'positive':'negative'}">${signed(p.out-p.buy)}</strong></button>`).join('')}<p class="hint">Player results sum to ${signed(-t.rake)} because rake leaves the table. Payout records do not change poker results.</p><div class="actions">${btn('Results & settlement','history-settle','primary')}${btn(isPlatform?'Export transactions':'Download sample CSV','csv','secondary')}</div>`}
