function settingsPage(){if(isPlatform)return header('Settings','Your preferences. Your records.')+`<div class="settings-row"><span>Dark appearance</span>${CashUI.toggle({label:'Dark appearance',checked:document.documentElement.dataset.theme==='dark',action:'theme'})}</div><div class="settings-action-group">${CashUI.actionRow({label:myContact()?'My contact':'Create my contact',description:myContact()?.name||'Save your details for banker selection',action:'my-contact'})}</div><div class="section-head"><h3>Save & recovery</h3></div><div id="backup-panel-mount">${window.CashBackupUI?CashBackupUI.panel():'Opening device storage…'}</div><div class="settings-action-group">${CashUI.actionRow({label:'Save an independent copy',description:'Full backup · records, photos and audit history',action:'backup'})}${CashUI.actionRow({label:'Restore a saved backup',description:'Review the file before replacing local records',action:'restore'})}${CashUI.actionRow({label:'Export transaction CSV',description:'Detailed analysis data · full restore uses a backup',action:'csv'})}</div><div id="device-recovery-mount"></div><a class="settings-row library-link" href="../../downloads/">Phone installation guide ↗</a><p class="hint">Full backups include photos and the audit ledger. CSV is a private analysis export; share summaries exclude contact details.</p>`;return header('Settings','Your preferences. Your records.')+`<div class="section-head"><h3>Appearance</h3></div><div class="settings-row"><span>Dark appearance<small>Switch between light and dark</small></span>${CashUI.toggle({label:'Dark appearance',checked:document.documentElement.dataset.theme==='dark',action:'theme'})}</div><div class="section-head"><h3>Backup & recovery</h3></div><div id="backup-panel-mount">${window.CashBackupUI?CashBackupUI.panel():'<p class="hint">Backup settings are loading.</p>'}</div><button class="settings-row" data-action="backup"><span>Export full demo backup<small>All demo tables, players, payments & activity</small></span><span>↓</span></button><button class="settings-row" data-action="restore"><span>Restore demo backup<small>Preview before replacing sample data</small></span><span>↑</span></button><a class="settings-row library-link" href="library.html">Reusable component library <span>↗</span></a><div class="section-head"><h3>Preview scenarios</h3></div>${[['active','Mid-game'],['balanced','Ready to settle'],['unbalanced','Balance mismatch'],['credit','Unpaid buy-ins / direct settlement'],['empty','Empty table'],['save-error','Simulated save failure']].map(([id,label])=>`<button class="settings-row" data-action="scenario" data-value="${id}">${label}<span>↗</span></button>`).join('')}`}
function insightsPage(){if(!CashHistory.completed(statsTables()).length)return firstRunHeading('Insights','A little perspective on your game nights.')+CashUI.emptyScene({kind:'history',title:'Let your history take shape.',description:'Completed cash games will build player results, session trends and a clearer view of your game nights.',primary:{label:!untouchedWorkspace()&&!table.closed?'Back to your table':'Create your first game',action:!untouchedWorkspace()&&!table.closed?'table':'new-table'},footnote:'Live stacks, unfinished games and tournaments aren’t counted here.'});const tables=CashHistory.completed(statsTables()),buy=tables.reduce((n,t)=>n+t.players.reduce((s,p)=>s+p.buy,0),0),rake=tables.reduce((n,t)=>n+t.rake,0),seats=tables.reduce((n,t)=>n+t.players.length,0),ranked=contacts.map(p=>({...p,stats:CashHistory.stats(tables,p.id)})).filter(p=>p.stats.sessions).sort((a,b)=>b.stats.net-a.stats.net);return header('A clearer picture',`${isPlatform?'Saved table history':'Calculated demo history'} · not live stacks`)+`<div class="stats stats-main">${stat('Tables',tables.length)}${stat('Players',ranked.length)}${stat('Seats played',seats)}</div><section class="hero"><span class="eyebrow">TOTAL BUY-IN VOLUME</span><div class="amount">${money(buy)}</div><div class="metrics"><div><small>Total rake</small><strong>${money(rake)}</strong></div><div><small>Average per seat</small><strong>${seats?money(Math.round(buy/seats)):'—'}</strong></div></div></section><div class="section-head"><h3>Buy-ins by table</h3><small>Oldest → newest</small></div><div class="history-bars" role="group" aria-label="Buy-ins by table: ${esc(tables.map(t=>t.date+' '+money(t.players.reduce((n,p)=>n+p.buy,0))).join('; '))}">${tables.map(t=>{const value=t.players.reduce((n,p)=>n+p.buy,0),max=Math.max(...tables.map(x=>x.players.reduce((n,p)=>n+p.buy,0)));return `<button data-action="recent" data-table-id="${esc(t.id)}" aria-label="${esc(t.name)}: ${money(value)}"><span style="height:${Math.max(4,value/max*100)}%"></span><small>${t.date.slice(-2)}</small></button>`}).join('')}</div><p class="hint">Tap a bar to inspect its table records.</p><div class="section-head"><h3>Player results</h3><span class="tag">By net result</span></div>${ranked.map((p,i)=>`<button class="session-row" data-action="profile" data-id="${p.id}"><span class="rank">${i+1}</span>${avatar(p)}<span class="grow"><strong>${esc(p.name)}</strong><small>${p.stats.sessions} sessions · ${p.stats.winRate}% wins</small></span><strong class="${p.stats.net>=0?'positive':'negative'}">${signed(p.stats.net)}</strong></button>`).join('')||'<p class="hint">No completed results yet.</p>'}<p class="hint">Winning = final cash-out greater than total buy-in. Past results do not predict future performance.</p><div class="notice">CSV import and the full insights engine remain phase two. Statistics use the completed records shown here.</div>`}
function modal(title,kicker,body,submit){
  formDirty=false;
  $('#sheet-title').textContent=title;
  $('#sheet-kicker').textContent=kicker;
  $('#sheet-body').innerHTML=body;
  let submitting=false;
  $('#sheet-form').onsubmit=async e=>{
    e.preventDefault();
    if(submitting||!submit||e.submitter?.disabled)return;
    submitting=true;
    try{await CashPolish.pending(e.submitter||$('#sheet-form button[type=submit]'),submit)}catch(error){notify(error.message||'Could not finish. Your entry is kept.')}finally{submitting=false}
  };
  if(!sheet.open)sheet.showModal();
  CashMotion.enter($('#sheet-body'),'content');
}

function playerForm(id,{self=false,seatAfter=false}={}){
 const p=contacts.find(x=>x.id===Number(id)),ownForm=self||Boolean(p?.isSelf),currentSelf=myContact(true);
 if(!p&&contacts.length>=1000)return notify('This workspace supports up to 1,000 saved players.');
 modal(ownForm?'Your contact':p?'Edit contact':'New contact','CONTACT DETAILS',`<div class="contact-form"><p class="muted">${ownForm?'Save your details once. Pick yourself as banker when you host, with your name on receipts.':'Save a contact now. Add them to a game whenever you’re ready.'}</p><div class="contact-photo-row"><span class="contact-photo-avatar">${p?avatar(p):CashUI.icon('players',27)}</span><label for="photo">${p?.photo?'Change photo':'Add a photo'}<small>Optional · for your player card</small></label><input class="sr-only" type="file" id="photo" name="contact-photo" aria-describedby="photo-status" accept="image/png,image/jpeg,image/webp,image/gif"></div><p id="photo-status" class="contact-photo-status" role="status"></p><label for="player-name">Full name <small>required</small></label><input id="player-name" class="contact-name" name="contact-name" autocomplete="name" enterkeyhint="next" maxlength="60" pattern=".*\\S.*" required aria-invalid="false" value="${esc(p?.name??'')}" placeholder="${ownForm?'Your name':'Player name'}"><p class="contact-error" id="contact-name-error">Enter a full name.</p><label for="phone">Phone number <small>optional</small></label><input id="phone" name="contact-phone" type="tel" autocomplete="tel" enterkeyhint="done" maxlength="60" value="${esc(p?.phone??'')}" placeholder="Add a phone number"><div id="duplicate-warning"></div>${ownForm?'<span class="my-contact-badge">My contact</span>':`<label class="check"><input id="contact-self" type="checkbox"> This is my contact</label><p class="hint">${currentSelf?'If selected, this replaces the My contact label on '+esc(currentSelf.name)+'. Existing banker assignments stay unchanged.':'Choose yourself as banker faster on future games.'}</p>`}<p class="hint">${p?.archived?'Saving restores this archived contact. ':''}Saving these details doesn’t add a seat, record a buy-in or share contact details.</p><span id="contact-feedback" class="sr-only" aria-live="polite"></span><button type="submit" class="primary">${seatAfter&&!p?'Save & review buy-in':ownForm?'Save my contact':'Save contact'}</button></div>`,async()=>{
 const name=$('#player-name').value.trim();if(!name)return;
 const phoneKey=$('#phone').value.replace(/\D/g,''),own=ownForm||Boolean($('#contact-self')?.checked);
 const duplicates=contacts.filter(c=>c.id!==p?.id&&!c.archived&&(c.name.trim().toLowerCase()===name.toLowerCase()||phoneKey.length>=7&&c.phone?.replace(/\D/g,'')===phoneKey));
 if(duplicates.length&&!$('#duplicate-ack')?.checked){$('#duplicate-warning').innerHTML=`<div class="notice">Similar player already saved: ${duplicates.map(x=>esc(x.name)).join(', ')}.</div><label class="check"><input type="checkbox" id="duplicate-ack"> This is a different person.</label>`;notify('Check the existing player before creating another.');return}
 const file=$('#photo').files[0];let photo=p?.photo;if(file){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){notify('Use a PNG, JPEG, WebP, or GIF photo');return}if(file.size>3000000){notify('Choose an image smaller than 3 MB');return}photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the photo. Choose it again.'));reader.readAsDataURL(file)})}
 const phone=$('#phone').value.trim();let savedId;
 await persistChange(p?'player-edited':'player-created',()=>{
  let target=p?contacts.find(c=>c.id===p.id):null;if(p&&!target)throw Error('This contact changed. Reopen it before saving.');
  if(!target){target={id:nextId++,last:500000};contacts.push(target)}
  Object.assign(target,{name,phone,...(photo?{photo}:{})});
  if(own){for(const c of contacts)if(c.id!==target.id)delete c.isSelf;target.isSelf=true;target.archived=false}
  if(!table.closed){const seated=table.players.find(x=>x.id===target.id);if(seated)Object.assign(seated,{name,phone,...(photo?{photo}:{})});if(table.bankerId===target.id)table.banker=name}
  savedId=target.id;
 },{subjectId:p?.id??nextId});
 forceClose();if(seatAfter&&!p)seat(savedId);else if(own){savedContactId=savedId;go('contact-saved')}else if(p)render();else go('players');
 });
}
let contactErrorTimer;
function syncContactError(input){let invalid;try{invalid=input.matches(':user-invalid')}catch{invalid=!input.validity.valid}input.setAttribute('aria-invalid',String(invalid));if(invalid)input.setAttribute('aria-describedby','contact-name-error');else input.removeAttribute('aria-describedby');return invalid}
document.addEventListener('invalid',e=>{if(e.target.id==='player-name')requestAnimationFrame(()=>syncContactError(e.target))},true);
document.addEventListener('blur',e=>{if(e.target.id!=='player-name')return;if(syncContactError(e.target)){clearTimeout(contactErrorTimer);const input=e.target;contactErrorTimer=setTimeout(()=>{const feedback=$('#contact-feedback');if(input.isConnected&&feedback)feedback.textContent='Full name: enter a full name.'},500)}},true);
document.addEventListener('input',e=>{if(e.target.id==='player-name'){clearTimeout(contactErrorTimer);syncContactError(e.target);const feedback=$('#contact-feedback');if(feedback)feedback.textContent=''}});

function seat(id){
  if(isPlatform&&!hasOpenGame())return createTable();
  if(table.players.length>=100)return notify('A table supports up to 100 players.');
  if(table.players.some(x=>x.id===Number(id)))return notify('Already seated at this table');
  if(table.type==='tournament')return tournamentJoin(Number(id));
  amountSheet('buy',id);
}
async function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
let receiptSnapshot=null;
