function shareModel(){return CashCore.summaryModel(historyView?recentData():table,paymentRecords())}
function summary(){const m=shareModel();return [m.name,isPlatform?'CASH OUT · TABLE SUMMARY':'CASH OUT · SAMPLE TABLE SUMMARY',`Banker: ${m.banker}`,m.totals.balanced?'Stacks balanced':!m.players.length?'No players or buy-ins recorded yet':`${m.totals.pending} cash-outs pending · difference ${money(m.totals.difference)}`,'',`Buy-ins: ${money(m.totals.buy)}`,`Cash-out stacks: ${money(m.totals.out)}`,` ${m.gameType==='tournament'?'Fees':'Rake'}: ${money(m.rake)} (distributed separately)`,'','PLAYER RESULTS',...m.players.map(p=>`${p.name} | In ${money(p.buy)} | Out ${p.out===null?'Playing':money(p.out)} | Result ${p.net===null?'Pending':signed(p.net)}`),'','PAYMENTS REMAINING',...(m.totals.balanced?m.transfers.length?m.transfers.map(t=>`${t.label}: ${money(t.amount)}`):['All player payments recorded.']:['Available after all stacks are entered and balanced.']),'','Records only · no real transfer occurs here.'].join('\n')}
function sharePreview(){const m=shareModel();return `<section class="share-summary" aria-label="Table summary"><div class="summary-heading"><span class="tag">${isPlatform?'Table summary':'Sample table'}</span><h3>${esc(m.name)}</h3><small>Banker · ${esc(m.banker)}</small></div><div class="row"><span>Total buy-ins</span><strong>${money(m.totals.buy)}</strong></div><div class="row"><span>Cash-out stacks</span><strong>${money(m.totals.out)}</strong></div><div class="row"><span>${m.gameType==='tournament'?'Fees':'Rake'} · handled separately</span><strong>${money(m.rake)}</strong></div><div class="notice ${m.totals.balanced?'good':''}">${m.totals.balanced?'✓ Stacks balance':!m.players.length?'No players or buy-ins recorded yet':`${m.totals.pending} cash-outs pending · difference ${money(m.totals.difference)}`}</div><h3>Player results</h3>${m.players.map(p=>`<div class="summary-player"><div><strong>${esc(p.name)}</strong><small>In ${money(p.buy)} · ${p.out===null?'Still playing':'out '+money(p.out)}</small></div><strong class="${p.net===null?'muted':p.net>=0?'positive':'negative'}">${p.net===null?'Pending':signed(p.net)}</strong></div>`).join('')}<div class="section-head"><h3>Payments remaining</h3></div>${m.totals.balanced?m.transfers.map(t=>`<div class="row"><span>${esc(t.label)}</span><strong>${money(t.amount)}</strong></div>`).join('')||'<p class="positive">All player payments recorded.</p>':'<p class="muted">Available after every stack is entered and the table balances.</p>'}</section>`}
function availableRoster(query=''){const q=query.trim().toLowerCase(),available=contacts.filter(c=>!c.archived&&!table.players.some(p=>p.id===c.id)),matches=available.filter(c=>c.name.toLowerCase().includes(q)||(c.phone||'').toLowerCase().includes(q));return matches.map(c=>`<div class="payment">${avatar(c)}<div class="grow"><strong>${esc(c.name)}</strong></div>${btn('Add','seat','',`data-id="${c.id}" aria-label="Add ${esc(c.name)}"`)}</div>`).join('')||`<p class="hint">${available.length?'No matching saved players. Try another name or phone number.':'Everyone in your roster is already seated.'}</p>`}
function createTable(type='cash'){
 const own=myContact();
 if(isPlatform&&table.players.length&&!table.closed){modal('You have a table in progress',table.name,`<p>Finish the current table before starting another. Its records and outstanding payments will stay in history.</p><div class="actions">${btn('Return to current table','table','primary')}</div>`);return}
 modal(type==='tournament'?'Create tournament':'Create a table','PRIVATE BY DEFAULT',`<label for="table-name">Table name</label><input id="table-name" placeholder="Friday Night" maxlength="60" required><label for="banker">Banker</label><select id="banker" required><option value="you" ${own?'':'selected'}>Enter banker’s name</option>${contacts.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${p.id===own?.id?'selected':''}>${esc(p.name)}${p.isSelf?' · Me':''}</option>`).join('')}</select><div id="host-details" ${own?'hidden':''}><label for="host-name">Banker’s full name <small>required</small></label><input id="host-name" name="banker-name" maxlength="60" autocomplete="name" placeholder="Name shown on receipts" ${own?'disabled':'required'}></div><p class="hint">Choose from saved players. Assigning the banker does not add a seat or record a payment.</p><div class="notice">${isPlatform?'Completed tables and outstanding payments stay in your history.':'Starting a new sample table replaces the current preview. Export a demo backup first to keep it.'}</div>${type==='tournament'?tournamentRulesFields():''}<div class="actions"><button class="primary" type="submit">Create private ${type==='tournament'?'tournament':'table'}</button></div>`,async()=>{
 const name=$('#table-name').value.trim(),selected=$('#banker').value,contact=contacts.find(p=>p.id===Number(selected)&&!p.archived);
 if(!name||selected!=='you'&&!contact)return;const hostName=$('#host-name').value.trim();if(selected==='you'&&!hostName){notify('Enter your name so receipts identify the banker.');$('#host-name').focus();return;}
 const rules=type==='tournament'?readTournamentRules():null;
 await persistChange('table-created',()=>{
  if(isPlatform&&table.closed)historyTables.push({...CashLedger.copy(table),payments:CashLedger.copy(payments)});
  table={...(isPlatform?emptyTable():initial()),id:crypto.randomUUID(),name,banker:contact?.name||hostName,...(contact?{bankerId:contact.id}:{}),players:[],rake:0,events:[],type,...(rules?{tournament:CashTournament.setup(rules)}:{})};payments=[];
 });playerFilter='all';historyView=false;forceClose();go('table');
 });
}

function csv(){const data=historyView?recentData():table;const cell=s=>'"'+String(s).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['table','player','buy_in_INR','cash_out_INR','net_INR','status'],...data.players.map(p=>[data.name,p.name,p.buy/100,p.out===null?'':p.out/100,p.out===null?'':(p.out-p.buy)/100,p.out===null?'playing':'cashed_out'])];download('cash-out-sample-summary.csv',rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');notify('Sample summary downloaded · not the phase-two CSV contract')}
function scenario(which,confirmed=false){if(window.CashBackupUI?.state()?.enabled&&!confirmed){modal('Replace this table with sample data?','PREVIEW SCENARIO',`<div class="notice">Device autosave is enabled. Loading a preview scenario will replace and save the current table. Export a full backup first to keep the existing records.</div><div class="actions"><button type="submit" class="primary">Load sample scenario</button></div>`,()=>scenario(which,true));return}playerFilter='all';forceClose();table=initial();payments=[];historyView=false;simulateSaveFailure=which==='save-error';if(which==='empty'){table.players=[];table.rake=0;table.events=[];go('table');return}if(!['active','save-error'].includes(which)){table.players[0].out=640000;table.players[1].out=which==='unbalanced'?200000:220000}if(which==='credit'){for(const p of table.players){p.paidIn=0;p.paidOut=0}table.mode='direct'}view=which==='balanced'||which==='unbalanced'?'review':which==='credit'?'settle':'table';forceClose();render();window.scrollTo(0,0);notify('Sample scenario loaded')}
document.addEventListener('change',e=>{if(e.target.id==='photo'){const file=e.target.files[0],status=$('#photo-status');if(status){status.textContent=!file?'No new photo selected.':!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)?'Use a PNG, JPEG, WebP, or GIF photo.':file.size>3000000?'Choose an image smaller than 3 MB.':'Selected: '+file.name}}if(e.target.id==='banker'){const typed=e.target.value==='you';$('#host-details').hidden=!typed;$('#host-name').disabled=!typed;$('#host-name').required=typed}});
document.addEventListener('input',e=>{if(e.target.id==='profile-session'&&view==='profile'){profileSession=Number(e.target.value);const host=document.createElement('div');host.innerHTML=CashProfile.chart(profileStats().trend,profileSession);const chart=e.target.closest('.co-chart');chart.querySelector('svg').outerHTML=host.querySelector('svg').outerHTML;chart.querySelector('.co-session-readout').innerHTML=host.querySelector('.co-session-readout').innerHTML;e.target.setAttribute('aria-valuetext',host.querySelector('input').getAttribute('aria-valuetext'));return}if(['player-name','phone'].includes(e.target.id)&&$('#duplicate-warning'))$('#duplicate-warning').innerHTML='';if(e.target.id==='amount'&&draft)amountInput(e.target);if(e.target.id==='seat-search')$('#available-roster').innerHTML=availableRoster(e.target.value);if(e.target.id==='player-search')$('#roster').innerHTML=roster(e.target.value)});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id),v=b.dataset.value,p=table.players.find(x=>x.id===id);try{switch(a){
case'history-filter':if(['all','cash','tournament'].includes(v)){historyFilter=v;render()}break;
case'player-filter':{if(!['all','playing','cashed','outstanding'].includes(v)||playerFilter===v)return;playerFilter=v;const update=()=>{$('#app .players').innerHTML=tableRoster();document.querySelectorAll('[data-action="player-filter"]').forEach(control=>{const selected=control.dataset.value===playerFilter;control.classList.toggle('active',selected);control.setAttribute('aria-pressed',String(selected))})};if(window.CashPremium)CashPremium.filter(update);else update();break;}
case'nav':historyView=false;go(v);break;case'table':case'tables':case'players':case'history':case'settings':case'review':if(sheet.open&&!formDirty)forceClose();historyView=false;go(a);break;
case'settle':historyView=false;if(playing().length||remaining()!==0)go('review');else go('settle');break;
case'theme':toggleTheme();break;
case'scenario':if(isPlatform)return;scenario(v);break;
case'rebuy':case'cashout':case'edit':case'reentry':amountSheet(a,id);break;case'rake':amountSheet('rake');break;case'rake-edit':amountSheet('rake-edit');break;
case'key':if(draft){draft.amount=v==='⌫'?draft.amount.slice(0,-1):v==='.'&&draft.amount.includes('.')?draft.amount:(draft.amount+(v==='.'&&!draft.amount?'0.':v));updateAmount()}break;
case'clear-amount':draft.amount='';updateAmount();break;
case'shortcut':addShortcut(v);break;
case'player-receipt':openPlayerReceipt(id);break;
case'receipt-share':await CashPolish.pending(b,()=>CashReceipt.share(receiptSnapshot));break;case'receipt-save':await CashPolish.pending(b,()=>CashReceipt.save(receiptSnapshot));break;
case'receipt-banker':if(historyView){notify('Archived banker details are read-only. Use the table summary for this legacy record.');break}modal('Banker details',table.name,`<label for="banker-full-name">Banker’s full name</label><input id="banker-full-name" maxlength="60" required value="${table.banker==='You'?'':esc(table.banker)}"><button class="primary" type="submit">Save banker name</button>`,async()=>{const name=$('#banker-full-name').value.trim();if(!name)return;await persistChange('banker-name-updated',()=>{table.banker=name});forceClose();render()});break;
case'my-contact':playerForm(myContact(true)?.id,{self:true});break;
case'new-player':playerForm(undefined,{seatAfter:b.dataset.seatAfter==='true'});break;case'edit-player':playerForm(id);break;
case'add-player':if(isPlatform&&!hasOpenGame()){createTable();break}modal('Add a player','SAVED PLAYERS',`<label class="sr-only" for="seat-search">Search players to add</label><input id="seat-search" class="search" type="search" placeholder="Search by name or phone" autocomplete="off"><div id="available-roster" class="detail-list available-roster" aria-live="polite">${availableRoster()}</div>${btn('+ Create new player','new-player','primary','data-seat-after="true"')}`);break;
case'seat':close();seat(id);break;
case'profile-tab':{if(!['overview','sessions'].includes(v)||profileTab===v)break;profileTab=v;const panel=$('#profile-panel');if(!panel){render();break}panel.innerHTML=profilePanel();panel.setAttribute('aria-labelledby','profile-tab-'+v);document.querySelectorAll('.co-tabs [role=tab]').forEach(tab=>{const selected=tab.dataset.value===v;tab.classList.toggle('active',selected);tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1});CashPolish.mount($('#app'));window.CashPremium?.panel(panel);break;}
case'profile':historyView=false;profileTab='overview';profileSession=null;profileId=id;view='profile';render();window.scrollTo(0,0);break;
case'archive':modal('Archive this player?','KEEP THEIR HISTORY',`<p class="muted">${esc(contacts.find(x=>x.id===id).name)} will leave your saved roster. Past tables and the current seat stay intact.</p><div class="actions">${btn('Archive player','confirm-archive','primary',`data-id="${id}"`)}</div>`);break;
case'confirm-archive':await persistChange('player-archived',()=>{contacts.find(x=>x.id===id).archived=true},{subjectId:id});close();go('players');notify('Player archived; table history retained');break;
case'player-menu':modal(p.name,'PLAYER ACTIONS',`${p.out!==null?btn('Return to play','reentry','settings-row',`data-id="${id}"`):''}${btn('Correct total buy-in','edit','settings-row',`data-id="${id}"`)}${btn('View payments','payment','settings-row',`data-id="${id}"`)}${btn('Remove from this table','remove','settings-row danger-link',`data-id="${id}"`)}<p class="hint">Corrections keep a trace in activity.</p>`);break;
case'remove':modal('Remove player?','CONFIRM REMOVAL',`<p class="muted">${esc(p.name)} has ${money(p.buy)} in buy-ins. Removing financial records would break this table’s history.</p><div class="notice">${!CashCore.canRemoveSeat(p,payments)?'Cash out and retain this player, or correct the recorded transactions.':'This empty seat has no financial records and can be removed.'}</div>${btn(!CashCore.canRemoveSeat(p,payments)?'Keep player':'Remove empty seat','confirm-remove','primary',`data-id="${id}"`)}`);break;
case'confirm-remove':await persistChange('empty-seat-removed',()=>{if(CashCore.canRemoveSeat(p,payments))table.players=table.players.filter(x=>x.id!==id)},{subjectId:id});forceClose();render();break;
case'payment':{const net=playerNet(p);modal('Player payments',p.name,`<div class="row"><span>Buy-ins received at entry</span><strong>${money(p.paidIn)}</strong></div><div class="row"><span>All cash-out stacks</span><strong>${money(p.out??p.priorOut??0)}</strong></div><div class="row total"><span>${net>0?'Still owes':net<0?'Still to receive':'No balance due'}</span><strong>${money(Math.abs(net))}</strong></div><p class="hint">Includes all recorded direct and banker payments. A stack entry never marks money as paid.</p>${payments.some(x=>!x.recent)?btn('Recorded payments & corrections','payment-log','settings-row'):''}<div class="actions">${net>0?btn('Record money received','mark-in','primary',`data-id="${id}"`):''}${net<0?btn('Record payout','mark-out','primary',`data-id="${id}"`):''}</div>`);break;}

case'mark-in':amountSheet('receive',id);break;
case'mark-out':amountSheet('payout',id);break;
case'close-table':if(CashCore.balance(table).balanced){await persistChange('table-closed',()=>{table.closed=true;event('Table closed','Balanced stacks')});historyView=false;go('settle')}break;
case'mode':if(!['banker','direct'].includes(v))return;await persistChange('settlement-mode-changed',()=>{table.mode=v});render();break;
case'record-transfer':{const t=transfers()[Number(b.dataset.index)];modal('Record this payment?','SETTLEMENT',`<div class="hero"><h3>${esc(t.label)}</h3><div class="amount">${money(t.amount)}</div><small>Confirm only after the money has changed hands.</small></div><div class="actions">${btn('Confirm payment recorded','confirm-transfer','primary',`data-index="${b.dataset.index}"`)}</div>`);break}
case'confirm-transfer':{if(!sheet.open)return;const t=transfers()[Number(b.dataset.index)];if(!t)return;await persistChange('settlement-payment',()=>{paymentRecords().push({...t,id:crypto.randomUUID(),timestamp:new Date().toISOString(),recent:false});if(!historyView)event('Settlement payment',`${t.label} · ${money(t.amount)}`)},{table:historyView?recentData():table});forceClose();render();notify('Payment saved on this device');break}
case'recent':if(b.dataset.tableId===table.id&&table.closed){historyView=false;go('review');break}if(!historyTables.some(t=>t.id===b.dataset.tableId))return;selectedHistoryId=b.dataset.tableId;historyView=true;go('history-detail');break;
case'history-detail':historyView=true;go('history-detail');break;
case'history-settle':historyView=true;go('settle');break;
case'payment-log':modal('Recorded payments','CORRECT A RECORD',`<p class="muted">Reversing a record corrects the app only. It does not move money back.</p><div class="detail-list">${paymentRecords().map((pay,index)=>!pay.recent?`<div class="payment"><div class="grow"><strong>${esc(pay.label||'Payment')}</strong><small>${money(pay.amount)} · ${pay.reversed?'reversed':pay.reverses?'correction':'recorded'}</small></div>${!pay.reversed&&!pay.reverses?btn('Correct','reverse-payment','',`data-index="${index}"`):''}</div>`:'').join('')||'<p>No payments recorded in this preview.</p>'}</div>`);break;
case'reverse-payment':{const pay=paymentRecords()[Number(b.dataset.index)];if(!pay||pay.reversed||pay.reverses)return;modal('Reverse this record?','PAYMENT CORRECTION',`<div class="hero"><h3>${esc(pay.label||'Payment')}</h3><div class="amount">${money(pay.amount)}</div></div><div class="notice">Only use this if the payment record was wrong. If actual money changed hands, leave that payment recorded. No real transfer occurs here.</div><label for="payment-reason">Reason for correction</label><input id="payment-reason" minlength="3" maxlength="160" required placeholder="For example, marked paid by mistake"><div class="actions"><button type="submit" class="primary">Confirm record reversal</button></div>`,async()=>{const reason=$('#payment-reason').value.trim();if(reason.length<3)return;await persistChange('payment-reversed',()=>{pay.id=pay.id||crypto.randomUUID();paymentRecords().push({id:crypto.randomUUID(),timestamp:new Date().toISOString(),from:pay.to,to:pay.from,amount:pay.amount,label:'Correction: '+(pay.label||'Payment'),recent:pay.recent,reverses:pay.id,reason});pay.reversed=true;if(!historyView)event('Payment record reversed',`${pay.label} · ${money(pay.amount)} · ${reason}`)},{reason,correction:true,paymentId:pay.id,table:historyView?recentData():table});forceClose();render();notify('Record reversed; outstanding amounts recalculated')});break;}
case'activity':if(isPlatform){CashBackupUI.activity();break}modal('Table activity','AUDIT TRAIL',`<p class="muted">${esc(table.name)} · INR · ₹${table.small}/₹${table.big} stakes</p><div class="detail-list">${table.events.map(x=>`<p><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></p>`).join('')}</div><p class="hint">Sample activity. Production records will retain stable IDs and full table snapshots.</p>`);break;
case'stakes':modal('Table stakes','OPTIONAL',`<p class="muted">Stakes describe the game. All buy-ins and cash-out stacks are entered as cash.</p><div class="two"><div><label for="small">Small blind · ₹</label><input id="small" type="number" min="1" max="100000" step="1" value="${table.small}" required></div><div><label for="big">Big blind · ₹</label><input id="big" type="number" min="1" max="100000" step="1" value="${table.big}" required></div></div><div class="actions"><button type="submit" class="primary">Save ${isPlatform?'':'sample '}stakes</button></div>`,async()=>{const s=Number($('#small').value),n=Number($('#big').value);if(![s,n].every(x=>Number.isInteger(x)&&x>0&&x<=100000)||n<s){notify('Use whole positive stakes; big blind must be at least the small blind');return}await persistChange('stakes-changed',()=>{table.small=s;table.big=n;event('Stakes changed',`${money(s*100)} / ${money(n*100)}`)});forceClose();render()});break;
case'call-settings':openCallSettings();break;
case'new-table':createTable();break;case'new-tournament':createTable('tournament');break;
case'table-menu':modal('Table options',table.name,`${btn('Call time · '+(table.callTimeMinutes??180)+' min','call-settings','settings-row')}${btn('Set stakes','stakes','settings-row')}${btn('View activity','activity','settings-row')}${btn(isPlatform?'Export transactions':'Download sample CSV','csv','settings-row')}${btn('Share summary','share','settings-row')}`);break;
case'cancel-restore':forceClose();break;
case'csv':if(isPlatform){CashBackupUI.csv();break}csv();break;
case'share':modal('Table summary','REVIEW BEFORE SHARING',`<p class="muted">Player names and amounts only. Phone numbers and photos stay private.</p>${sharePreview()}<div class="actions">${btn('Download summary','download-summary','primary')}</div><p class="hint">Preview only. Downloading does not send this to anyone.</p>`);break;
case'download-summary':await download(isPlatform?'cash-out-table-summary.txt':'cash-out-sample-summary.txt',summary(),'text/plain');close();break;
case'backup':if(isPlatform){CashBackupUI.export();break}download('cash-out-demo-backup.json',JSON.stringify({demo:true,version:1,table,contacts,payments,historyTables}), 'application/json');notify('Demo backup exported · not a production backup');break;
case'restore':if(isPlatform){CashBackupUI.import();break}modal('Restore demo backup','PREVIEW BEFORE REPLACING',`<p class="muted">Choose a demo JSON backup exported by this wireframe. Production backup/import is separate.</p><label for="backup-file">Demo backup</label><input id="backup-file" type="file" accept=".json" required><div class="actions"><button type="submit" class="primary">Preview backup</button></div><p class="hint">Or inspect the sample states without choosing a file.</p><div class="two">${btn('Valid example','restore-example','secondary')}${btn('Invalid example','restore-invalid','secondary')}</div>`,async()=>{const file=$('#backup-file').files[0];if(!file)return notify('Choose a demo backup file first.');if(file.size>10000000)return notify('Demo backup is too large.');try{previewRestore(JSON.parse(await file.text()))}catch(error){notify(error.message||'Not a supported demo backup.')}});break;
case'restore-example':{if(isPlatform)return;const t=initial();t.name='Backup preview example';previewRestore({demo:true,version:1,table:t,contacts:CashHistory.seed().contacts,payments:[],historyTables:CashHistory.seed().tables});break}
case'restore-invalid':if(isPlatform)return;try{previewRestore({demo:true,version:1,table:{name:'Invalid example'}})}catch(error){notify(error.message)}break;

case'cloud':go('settings');break;
case'insights-preview':modal('CSV quality check','PHASE TWO PREVIEW',`<div class="notice good">Example: 12 tables · 24 players · 186 events</div><div class="row"><span>Schema and IDs</span><strong class="positive">Valid</strong></div><div class="row"><span>Balanced completed tables</span><strong>11</strong></div><div class="row"><span>Unfinished tables</span><strong>1 excluded</strong></div><p class="hint">Illustrative state only. No CSV has been imported and no engine runs yet.</p>`);break;
}}catch(error){notify(error.message||'The change could not be saved.')}});
function previewRestore(data){
  if(isPlatform)return CashBackupUI.import();
  CashCore.validateBackup(data);
  CashHistory.validate(data.historyTables||[],data.contacts,CashCore);
  modal('Restore this sample?','BACKUP PREVIEW',`<div class="hero"><h3>${esc(data.table.name)}</h3><p>${data.table.players.length} seated players · ${(data.historyTables||[]).length} past tables · ${data.table.events.length} activity entries</p></div><p class="notice">Replaces the sample data currently shown. Current sample changes will be lost. This is a demo archive, not production recovery.</p><div class="actions"><button type="submit" class="primary">Restore demo data</button>${btn('Cancel','cancel-restore','secondary')}</div>`,()=>{table=data.table;contacts=data.contacts;payments=data.payments;historyTables=data.historyTables||[];selectedHistoryId=historyTables.at(-1)?.id;nextId=Math.max(10,...contacts.map(p=>p.id+1));historyView=false;forceClose();go('table');notify('Demo backup restored')});
}
function applyTheme(theme){const dark=theme!=='light';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme').innerHTML=CashUI.icon(dark?'sun':'moon');$('#theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme')}
function toggleTheme(){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{window.localStorage?.setItem('cash-out-appearance',theme)}catch{}if(view==='settings')render()}
try{const theme=window.localStorage?.getItem('cash-out-appearance');if(theme==='dark'||theme==='light')applyTheme(theme)}catch{}
$('#prototype-wordmark').innerHTML=CashUI.wordmark('compact');$('#sidebar-wordmark').innerHTML=CashUI.wordmark('large');
applyTheme(document.documentElement.dataset.theme);$('#theme').onclick=toggleTheme;
$('#close-sheet').onclick=close;
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
sheet.addEventListener('cancel',e=>{e.preventDefault();close()});
render();
